from pathlib import Path
import json,os,hashlib,collections,csv
OUT=Path(os.environ.get('EQ_OUT',str(Path(__file__).resolve().parents[1])))
R=OUT/'results'; manifest=json.loads((OUT/'source_manifest.json').read_text());suite=json.loads((R/'suite_results.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
summary={'scope':'Reset-reachable unbounded digital sequential equivalence, default parameters, ideal Boolean/Liberty semantics','tool':manifest['yosys_version'],'proofs':[],'source_sha256':manifest['source_sha256'],'model_sha256':manifest['model_sha256'],'output_coverage':{},'functional_cell_audit':{}}
for p in sorted(R.glob('*_coverage.json')):
 c=json.loads(p.read_text());label=c['label']; step=suite.get(label,{}).get('status','UNKNOWN');base=suite.get(label+'_reset',{}).get('status','UNKNOWN');result='PASS' if step==base=='PASS' else 'UNKNOWN'
 row={'comparison':label,'result':result,'inductive_step':step,'reset_base':base,'gold_state_bits':c['gold_state_bits'],'gate_state_bits':c['gate_state_bits'],'output_bits':c['output_bits'],'inductive_obligations':len(c['proof_obligations']),'reset_obligations':c['gate_state_bits']+2+(c['gold']=='rtl'),'condition':c['condition'],'power_ports':c['power_ports']};summary['proofs'].append(row)
 outs=collections.Counter(x['name'].split()[1].split('[')[0] for x in c['proof_obligations'] if x['name'].startswith('output '))
 summary['output_coverage'][label]={k:{'bits':v,'status':result} for k,v in outs.items()}
for label in manifest['config']['netlists']:
 p=R/f'{label}_preflatten.json'
 if not p.exists():continue
 d=json.loads(p.read_text())['modules'];top=d['sar_digi_paper_core'];counts=collections.Counter(c['type'] for c in top['cells'].values() if c['type']!='$scopeinfo');phys={}
 for ty in counts:
  assert ty in d,(label,ty,'unmodeled cell');m=d[ty]
  assert not int(m.get('attributes',{}).get('blackbox','0'),2),(label,ty,'blackbox cell')
  if not any(v['direction']=='output' for v in m['ports'].values()):phys[ty]=counts[ty]
 n=json.loads((R/f'{label}.json').read_text())['modules']['sar_digi_paper_core'];types=collections.Counter(c['type'] for c in n['cells'].values());assert set(types)<= {'$_DFF_PN0_','$_DFF_PN1_','$_AND_','$_OR_','$_XOR_','$_XNOR_','$_NOT_','$_MUX_','$scopeinfo'}
 assert not any(b in ('x','z') for c in n['cells'].values() if c['type']!='$scopeinfo' for bs in c.get('connections',{}).values() for b in bs)
 summary['functional_cell_audit'][label]={'instantiated_types':dict(counts),'physical_only_no_output_cells':phys,'normalized_primitive_counts':dict(types),'unsupported_functional_cells':0,'x_z_connections':0}
