for p,h in manifest['source_sha256'].items():rows.append(f'- `{p}`: `{h}`')
rows.extend(['','## Reproduction','','Source the pinned environment, set EQ_OUT to this evidence directory, and run the shared runner:','','```bash','source /workspace/scratch/5988101d3fa5/sar16_antenna_repair_20261006/environment/env.sh',f'export EQ_OUT="{OUT}"','python /workspace/scratch/5988101d3fa5/sar16_antenna_repair_20261006/equivalence/scripts/run_suite.py','python /workspace/scratch/5988101d3fa5/sar16_antenna_repair_20261006/equivalence/scripts/collect_report.py','```','','config.json identifies exact source and library paths. A changed pinned input aborts reproduction; use a new evidence directory for a new design. Results apply only to the hashes above.'])
